import { describe, it, expect } from "vitest";
import { runScenario } from "./claimOffice.js";

describe("MHPCO Claim Office", () => {
  // --- Premium: empty and base premiums ---
  it.todo("empty item list -> premium 5 G (only processing fee)");
  it.todo("single sword (newcomer, no modifiers) -> base 100 + first insurance 10 + fee 5 = 115");

  // --- Component base premiums and blocks ---
  it.todo("2 runes -> base 50 (no block)");
  it.todo("3 runes -> base 60 (block applies, exactly 3)");
  it.todo("4 runes -> base 100 (no block; block requires exactly 3)");
  it.todo("7 runes -> base 175 (no block)");
  it.todo("2 runes + 1 moonstone -> base 75 (no block: different types)");
  it.todo("3 runes + 3 moonstones -> base 120 (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("newcomer cursed sword (steel, ench 3) -> premium 165");
  it.todo("sword with enchantment exactly 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed sword ench 5 -> both curse and high-enchantment surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("cursed sword + plain amulet -> curse surcharge only on cursed item's base (210 before fee)");

  // --- Rounding ---
  it.todo("premium calc yielding 197.5 -> 198 (rounded up in MHPCO favor)");

  // --- Follow-up contracts / integration ---
  it.todo("long-standing customer's second quote: cursed sword ench 7 -> premium 160");

  // --- Errors: quote ---
  it.todo("quote with unknown item type -> CLI exits non-zero, writes stderr, no results");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel ench 3) damage 500 -> payout 400 (minus deductible)");
  it.todo("rune (value 250) damage 200 -> payout 100 (minus deductible, no special clause)");

  // --- Claim: enchantment vs dragon material clauses ---
  it.todo("dragon sword ench 8 damage 1000 -> payout 400 (50% then deductible)");
  it.todo("dragon sword ench 9 damage 1000 -> payout 400 (50% wins, then deductible)");
  it.todo("dragon sword ench 5 damage 800 -> payout 700 (full reimbursement, then deductible)");
  it.todo("steel sword ench 9 damage 1000 -> payout 400 (50% then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack sword 500 + amulet 300 -> payout 600 (deductible per damaged item)");

  // --- Claim: cap based on insurance sum ---
  it.todo("cursed sword premium modifiers do not raise cap -> cap 2000");
  it.todo("cap exhaustion: two 1500 claims on sword -> 1400 then 600, remainingCap 0");

  // --- Claim: multiple items of same type ---
  it.todo("two swords, dragon attack on both -> each damage its own deductible");
  it.todo("more sword damages than swords insured -> CLI exits non-zero (claim rejected)");

  // --- Claim: rounding ---
  it.todo("payout calc yielding 350.5 -> payout 350 (rounded down in MHPCO favor)");

  // --- Errors: claim ---
  it.todo("claim references item not in policy -> CLI exits non-zero, writes stderr");
  it.todo("claim with negative damage amount -> CLI exits non-zero, writes stderr");

  // --- CLI end-to-end ---
  it.todo("CLI reads scenario JSON from stdin and writes results JSON to stdout");
});

