const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

interface Customer {
  yearsWithMHPCO: number;
}

interface Item {
  type: string;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

type Step = QuoteStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

interface QuoteResult {
  premium: number;
}

interface ScenarioResult {
  results: QuoteResult[];
}

function itemBasePremium(item: Item): number {
  return BASE_PREMIUM[item.type];
}

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
  return Math.ceil(policyBase + firstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
}

